 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; class PluginController extends AddonController { protected function directory(): string { return '/plugins'; } protected function sources(): array { return $this->catalogue->curseforgeConfigured() ? ['modrinth', 'spigot', 'curseforge'] : ['modrinth', 'spigot']; } protected function projectTypes(): array { return ['plugin', 'mod']; } protected function loaders(): array { return [ 'paper', 'spigot', 'bukkit', 'folia', 'purpur', 'sponge', 'bungeecord', 'velocity', 'waterfall', 'geyser', ]; } protected function curseforgeClass(): int { return 5; } protected function usageKind(): string { return 'plugin'; } } 